const temperatury = [12, 25, 3, 40, -5];

console.log(Math.max.apply(null, temperatury)); // 40
console.log(Math.min.apply(null, temperatury)); // -5

function zbuduj(a, b, c) {
  return this.prefix + [a, b, c].join("-");
}

console.log(zbuduj.apply({ prefix: "kod" }, [1, 2, 3])); // "kod1-2-3"

function sumuj3(a, b, c) {
  return a + b + c;
}

console.log(sumuj3.apply(null, [5, 10, 15])); // 30

function opisPodrozy(cel, dni) {
  return `${this.imie} jedzie do ${cel} na ${dni} dni`;
}

console.log(opisPodrozy.apply({ imie: "Marek" }, ["Rzym", 7]));
// "Marek jedzie do Rzym na 7 dni"

function polaczSlowa(a, b, c) {
  return `${a} ${b} ${c}`;
}

console.log(polaczSlowa.call(null, "Ala", "ma", "kota"));      // "Ala ma kota"
console.log(polaczSlowa.apply(null, ["Ala", "ma", "kota"]));   // "Ala ma kota"
// Oba wywolania daja identyczny wynik - jedyna roznica to sposob podania
// argumentow: call() po przecinku, apply() jako jedna tablica.

const oceny = [4, 5, 3, 5, 2, 4];

console.log(Math.max.apply(null, oceny)); // 5 - starszy sposob
console.log(Math.max(...oceny));           // 5 - nowoczesny sposob (spread operator)
// Oba dają identyczny wynik. Spread operator jest krotszy i czytelniejszy,
// dlatego apply() jest dzis rzadziej uzywane do tego konkretnego celu -
// apply() pozostaje przydatne glownie gdy jednoczesnie potrzeba jawnie
// ustawic this, czego sam spread operator nie robi.

function przedstawZFirma(firma) {
  return `${this.imie} pracuje w ${firma}`;
}

const dane = [["TechCorp"], ["DataSoft"]];
const osoby = [{ imie: "Kasia" }, { imie: "Tomek" }];

for (let i = 0; i < osoby.length; i++) {
  console.log(przedstawZFirma.apply(osoby[i], dane[i]));
}
// "Kasia pracuje w TechCorp"
// "Tomek pracuje w DataSoft"

const uzytkownicy = [
  { imie: "Ala", wiek: 30 },
  { imie: "Jan", wiek: 45 },
  { imie: "Ola", wiek: 22 }
];

const wieki = uzytkownicy.map(u => u.wiek);
console.log(Math.max.apply(null, wieki)); // -> 45

function sumuj(a, b, c) {
  return a + b + c;
}

function srednia() {
  return sumuj.apply(null, arguments) / arguments.length;
}

console.log(srednia(2, 4, 6)); // -> 4

function dolacz(a, b) {
  Array.prototype.push.apply(a, b);
}

const a = [1, 2];
dolacz(a, [3, 4]);
console.log(a); // -> [1, 2, 3, 4]

const tablica = Array.apply(null, Array(3)).map((_, i) => i * 2);
console.log(tablica); // -> [0, 2, 4]
// Array(3) ma "dziury", ktore map pomija. apply przekazuje je jako trzy argumenty undefined,
// wiec Array(undefined, undefined, undefined) tworzy tablice z prawdziwymi elementami.

function loguj(fn) {
  return function () {
    console.log("wywolanie");
    return fn.apply(this, arguments);
  };
}

const o = {
  n: 2,
  mnoz: loguj(function (x) {
    return x * this.n;
  })
};

console.log(o.mnoz(5));
// -> "wywolanie"
// -> 10

function wywolajZTablica(fn, obiekt, tablica) {
  return fn.apply(obiekt, tablica);
}

function opisz(a, b) {
  return this.n + a + b;
}

console.log(wywolajZTablica(opisz, { n: 1 }, [2, 3])); // -> 6

function podnies(procent) {
  return this.cena * (1 + procent / 100);
}

const produkt = { cena: 100 };
console.log(podnies.apply(produkt, [20])); // -> 120

try {
  podnies.apply(produkt, 20);
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

function f(a, b) {
  return this.n + a + b;
}

const o = { n: 5 };
const args = [1, 2];

console.log(f.call(o, ...args)); // -> 8
console.log(f.apply(o, args));   // -> 8

console.log(Math.max.apply(null, [])); // -> -Infinity
console.log(Math.min.apply(null, [])); // -> Infinity
// Pusta lista argumentow: max startuje od -Infinity, a min od Infinity.

function dodaj(a, b) {
  return a + b;
}

function przekaz() {
  return dodaj.apply(null, arguments);
}

console.log(przekaz(3, 4)); // -> 7

const sportowcy = [
  { imie: "A", wynik: 10 },
  { imie: "B", wynik: 30 },
  { imie: "C", wynik: 20 }
];

console.log(Math.max.apply(null, sportowcy.map(s => s.wynik))); // -> 30

const stos = {
  el: [],
  dodaj(...x) {
    this.el.push(...x);
  }
};

stos.dodaj.apply(stos, [1, 2, 3]);
console.log(stos.el); // -> [1, 2, 3]

function bezPierwszego() {
  return Array.prototype.slice.apply(arguments, [1]);
}

console.log(bezPierwszego(1, 2, 3)); // -> [2, 3]

function f(a, b) {
  return [a, b];
}

console.log(f.apply(null, { length: 2, 0: "x", 1: "y" })); // -> ["x", "y"]
// apply akceptuje takze obiekty tablicopodobne (indeksy + length).

function sumuj(a, b) {
  return a + b;
}

const pary = [[1, 2], [3, 4], [5, 6]];
console.log(pary.map(para => sumuj.apply(null, para))); // -> [3, 7, 11]

function f(a = 10) {
  return a + this.n;
}

console.log(f.apply({ n: 1 }));      // -> 11 (brak argumentow -> a = 10)
console.log(f.apply({ n: 1 }, [5])); // -> 6

try {
  Math.max.apply(null, "123");
} catch (e) {
  console.log(e.name); // -> "TypeError"
}

console.log(Math.max(..."123")); // -> 3
// apply nie przyjmuje prymitywnego napisu jako listy argumentow, a spread dziala na kazdym iterowalnym obiekcie.

function zsumujWszystko() {
  return Array.prototype.reduce.apply(arguments, [(s, x) => s + x, 0]);
}

console.log(zsumujWszystko(1, 2, 3, 4)); // -> 10

function maksymalna() {
  return Math.max.apply(null, arguments);
}

console.log(maksymalna(4, 9, 2)); // -> 9

function wywolajWszystkie(funkcje, obiekt, argumenty) {
  return funkcje.map(fn => fn.apply(obiekt, argumenty));
}

function dodaj(a) { return this.n + a; }
function pomnoz(a) { return this.n * a; }

console.log(wywolajWszystkie([dodaj, pomnoz], { n: 3 }, [2])); // -> [5, 6]

